CREATE FUNCTION public.save_workforce_settings(_timezone text,_basis text,_threshold numeric,_multiplier numeric,_payroll boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin_or_manager(auth.uid()) OR NOT public.has_workspace_access(auth.uid(),'attendance') THEN RAISE EXCEPTION 'Attendance manager required'; END IF; IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=_timezone) OR _basis NOT IN ('daily','weekly') OR _threshold<=0 OR _threshold>(CASE WHEN _basis='daily' THEN 24 ELSE 168 END) OR _multiplier<1 OR _multiplier>5 THEN RAISE EXCEPTION 'Invalid clock or overtime settings'; END IF; INSERT INTO public.workforce_clock_settings(org_id,timezone,overtime_basis,overtime_threshold,overtime_multiplier,attendance_payroll) VALUES(public.current_org_id(),_timezone,_basis,_threshold,_multiplier,_payroll) ON CONFLICT(org_id) DO UPDATE SET timezone=_timezone,overtime_basis=_basis,overtime_threshold=_threshold,overtime_multiplier=_multiplier,attendance_payroll=_payroll; END $$;
REVOKE ALL ON FUNCTION public.save_workforce_settings(text,text,numeric,numeric,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.save_workforce_settings(text,text,numeric,numeric,boolean) TO authenticated;
CREATE FUNCTION public.configure_employee_clock(_employee uuid,_code text,_pin text,_start time,_end time,_days integer[],_break integer,_site uuid DEFAULT NULL,_enabled boolean DEFAULT true) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE o uuid:=public.current_org_id(); BEGIN IF NOT public.is_admin_or_manager(auth.uid()) OR NOT public.has_workspace_access(auth.uid(),'attendance') OR public.employee_org_id(_employee) IS DISTINCT FROM o THEN RAISE EXCEPTION 'Attendance manager in the employee company required'; END IF; IF _code IS NULL OR _code !~ '^[A-Za-z0-9_-]{2,40}$' OR _pin IS NOT NULL AND _pin !~ '^[0-9]{4,6}$' OR _start IS NULL OR _end IS NULL OR _start=_end OR coalesce(cardinality(_days),0)<1 OR NOT _days<@ARRAY[0,1,2,3,4,5,6] OR _break IS NULL OR _break<0 OR _break>240 THEN RAISE EXCEPTION 'Invalid employee clock configuration'; END IF; IF _site IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.client_sites WHERE id=_site AND org_id=o AND latitude IS NOT NULL AND longitude IS NOT NULL) THEN RAISE EXCEPTION 'Choose a configured company site'; END IF; IF _pin IS NOT NULL THEN INSERT INTO public.workforce_clock_credentials(org_id,employee_id,employee_code,pin_hash,enabled) VALUES(o,_employee,_code,crypt(_pin,gen_salt('bf',10)),_enabled) ON CONFLICT(org_id,employee_id) DO UPDATE SET employee_code=_code,pin_hash=crypt(_pin,gen_salt('bf',10)),enabled=_enabled,failed_attempts=0,locked_until=NULL; ELSE UPDATE public.workforce_clock_credentials SET enabled=_enabled,employee_code=_code WHERE org_id=o AND employee_id=_employee; END IF; INSERT INTO public.workforce_schedules(org_id,employee_id,shift_start,shift_end,days_of_week,break_minutes,site_id,enabled) VALUES(o,_employee,_start,_end,_days,_break,_site,_enabled) ON CONFLICT(org_id,employee_id) DO UPDATE SET shift_start=_start,shift_end=_end,days_of_week=_days,break_minutes=_break,site_id=_site,enabled=_enabled; END $$;
REVOKE ALL ON FUNCTION public.configure_employee_clock(uuid,text,text,time,time,integer[],integer,uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.configure_employee_clock(uuid,text,text,time,time,integer[],integer,uuid,boolean) TO authenticated;
CREATE FUNCTION public.workforce_pin_employee(_org uuid,_code text,_pin text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE c public.workforce_clock_credentials; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Trusted clock service required'; END IF; SELECT * INTO c FROM public.workforce_clock_credentials WHERE org_id=_org AND employee_code=_code FOR UPDATE; IF c.employee_id IS NULL OR NOT c.enabled OR c.locked_until>now() THEN RETURN NULL; END IF; IF crypt(_pin,c.pin_hash)<>c.pin_hash THEN UPDATE public.workforce_clock_credentials SET failed_attempts=failed_attempts+1,locked_until=CASE WHEN failed_attempts>=4 THEN now()+interval '15 minutes' ELSE NULL END WHERE org_id=_org AND employee_id=c.employee_id; RETURN NULL; END IF; UPDATE public.workforce_clock_credentials SET failed_attempts=0,locked_until=NULL WHERE org_id=_org AND employee_id=c.employee_id; RETURN c.employee_id; END $$;
REVOKE ALL ON FUNCTION public.workforce_pin_employee(uuid,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.workforce_pin_employee(uuid,text,text) TO service_role;
CREATE FUNCTION public.record_workforce_punch(_employee uuid,_org uuid,_direction text,_mode text,_lat double precision DEFAULT NULL,_lon double precision DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sh public.workforce_shifts; sc public.workforce_schedules; tz text; day date; start_at timestamptz; end_at timestamptz; geo json; hours numeric; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' OR _direction NOT IN ('clock_in','clock_out') OR _mode NOT IN ('device','pin','voice') THEN RAISE EXCEPTION 'Trusted clock request required'; END IF; IF NOT EXISTS(SELECT 1 FROM public.payroll_employee_directory WHERE user_id=_employee AND org_id=_org AND deleted_at IS NULL AND lower(status)='active') THEN RAISE EXCEPTION 'Active employee company required'; END IF; PERFORM pg_advisory_xact_lock(hashtext('workforce-'||_employee::text)); SELECT coalesce((SELECT timezone FROM public.workforce_clock_settings WHERE org_id=_org),'America/St_Lucia') INTO tz; day:=(now() AT TIME ZONE tz)::date; SELECT * INTO sc FROM public.workforce_schedules WHERE org_id=_org AND employee_id=_employee AND enabled; IF sc.site_id IS NOT NULL THEN IF _lat IS NULL OR _lon IS NULL OR _lat NOT BETWEEN -90 AND 90 OR _lon NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'Location permission required for this work site'; END IF; geo:=public.verify_guard_location(sc.site_id,_lat,_lon); IF NOT coalesce((geo->>'within_geofence')::boolean,false) THEN RAISE EXCEPTION 'You must be inside your assigned work site'; END IF; END IF; IF EXISTS(SELECT 1 FROM public.guard_assignments WHERE user_id=_employee AND org_id=_org AND is_active) AND sc.site_id IS NULL THEN RAISE EXCEPTION 'Manager must assign a clock work site for this guard'; END IF; SELECT * INTO sh FROM public.workforce_shifts WHERE org_id=_org AND employee_id=_employee AND clock_in IS NOT NULL AND clock_out IS NULL ORDER BY clock_in DESC LIMIT 1 FOR UPDATE; IF _direction='clock_in' AND sh.id IS NOT NULL THEN RAISE EXCEPTION 'Already clocked in; clock out first'; END IF; IF _direction='clock_out' AND sh.id IS NULL THEN RAISE EXCEPTION 'No open shift; ask your manager to review the missing clock-in'; END IF; IF _direction='clock_in' THEN IF sc.id IS NOT NULL THEN IF sc.shift_end<sc.shift_start AND (now() AT TIME ZONE tz)::time<sc.shift_end THEN day:=day-1; END IF; start_at:=(day+sc.shift_start) AT TIME ZONE tz; end_at:=((day+CASE WHEN sc.shift_end<sc.shift_start THEN 1 ELSE 0 END)+sc.shift_end) AT TIME ZONE tz; END IF; INSERT INTO public.workforce_shifts(org_id,employee_id,shift_date,scheduled_start,scheduled_end,clock_in,break_minutes) VALUES(_org,_employee,day,start_at,end_at,now(),coalesce(sc.break_minutes,0)) ON CONFLICT(org_id,employee_id,shift_date) DO UPDATE SET clock_in=now() WHERE workforce_shifts.clock_in IS NULL AND workforce_shifts.reviewed_at IS NULL RETURNING * INTO sh; IF sh.id IS NULL THEN RAISE EXCEPTION 'A shift already exists for today; ask your manager'; END IF; ELSE hours:=greatest(0,extract(epoch FROM(now()-sh.clock_in))/3600-sh.break_minutes/60.0); UPDATE public.workforce_shifts SET clock_out=now(),approved_hours=CASE WHEN hours<=24 AND NOT EXISTS(SELECT 1 FROM public.workforce_alerts WHERE shift_id=sh.id AND resolved_at IS NULL) THEN round(hours,4) ELSE NULL END,review_status=CASE WHEN hours<=24 AND NOT EXISTS(SELECT 1 FROM public.workforce_alerts WHERE shift_id=sh.id AND resolved_at IS NULL) THEN 'complete' ELSE 'pending' END WHERE id=sh.id; END IF; INSERT INTO public.workforce_punches(org_id,employee_id,shift_id,direction,mode,latitude,longitude) VALUES(_org,_employee,sh.id,_direction,_mode,_lat,_lon); RETURN jsonb_build_object('direction',_direction,'punched_at',now(),'next',CASE WHEN _direction='clock_in' THEN 'clock_out' ELSE 'clock_in' END); END $$;
REVOKE ALL ON FUNCTION public.record_workforce_punch(uuid,uuid,text,text,double precision,double precision) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.record_workforce_punch(uuid,uuid,text,text,double precision,double precision) TO service_role;